  "inlineSchema": "// SQLite en attendant le choix définitif Postgres/MariaDB à 3 (cf TO-DO_backend.md)\n// TODO migration Postgres : changer provider + url du datasource, repartir avec un historique\n// de migrations neuf (le SQL de prisma/migrations/*.sql est specifique a SQLite),\n// voir le TODO enum sur Friendship.status plus bas\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\nmodel User {\n  id                     Int            @id @default(autoincrement())\n  username               String         @unique\n  email                  String         @unique\n  password_hash          String?\n  display_name           String\n  avatar_url             String?\n  is_online              Boolean        @default(false)\n  last_seen_at           DateTime?\n  created_at             DateTime       @default(now())\n  updated_at             DateTime       @updatedAt\n  oauthAccounts          OAuthAccount[]\n  attempts               QuizAttempt[]\n  sentFriendRequests     Friendship[]   @relation(\"FriendshipRequester\")\n  receivedFriendRequests Friendship[]   @relation(\"FriendshipAddressee\")\n  blockedUsers           BlockedUser[]  @relation(\"BlockedUserBlocker\")\n  blockedByUsers         BlockedUser[]  @relation(\"BlockedUserBlocked\")\n  quizzes                Quiz[]         @relation(\"QuizOwner\")\n  questions              Question[]     @relation(\"QuestionAuthor\")\n}\n\nmodel OAuthAccount {\n  id               Int      @id @default(autoincrement())\n  user_id          Int\n  user             User     @relation(fields: [user_id], references: [id], onDelete: Cascade)\n  provider         String\n  provider_user_id String\n  created_at       DateTime @default(now())\n\n  @@unique([provider, provider_user_id])\n}\n\nmodel Friendship {\n  id           Int      @id @default(autoincrement())\n  requester_id Int\n  requester    User     @relation(\"FriendshipRequester\", fields: [requester_id], references: [id], onDelete: Cascade)\n  addressee_id Int\n  addressee    User     @relation(\"FriendshipAddressee\", fields: [addressee_id], references: [id], onDelete: Cascade)\n  status       String   @default(\"pending\") // TODO: passer en enum (pending/accepted/declined) quand on migre vers Postgres, pas supporte par Prisma sur SQLite\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  @@unique([requester_id, addressee_id])\n}\n\nmodel BlockedUser {\n  id         Int      @id @default(autoincrement())\n  blocker_id Int\n  blocker    User     @relation(\"BlockedUserBlocker\", fields: [blocker_id], references: [id], onDelete: Cascade)\n  blocked_id Int\n  blocked    User     @relation(\"BlockedUserBlocked\", fields: [blocked_id], references: [id], onDelete: Cascade)\n  created_at DateTime @default(now())\n\n  @@unique([blocker_id, blocked_id])\n}\n\nmodel Quiz {\n  id          Int      @id @default(autoincrement())\n  title       String\n  description String?\n  createdAt   DateTime @default(now())\n\n  ownerId    Int?\n  owner      User?  @relation(\"QuizOwner\", fields: [ownerId], references: [id], onDelete: Cascade)\n  visibility String @default(\"public\") // \"public\" | \"friends\" | \"private\"\n\n  questions QuizQuestion[]\n  attempts  QuizAttempt[]\n}\n\nmodel Category {\n  id   Int    @id @default(autoincrement())\n  slug String @unique\n  name String @unique\n\n  questions Question[]\n  attempts  QuizAttempt[]\n}\n\nmodel Question {\n  id          Int      @id @default(autoincrement())\n  ref         String?  @unique // \"geo-001\" pour la banque, null pour une question perso\n  type        String   @default(\"multiple\") // \"multiple\" | \"boolean\"\n  difficulty  Int      @default(1) // 1 facile, 2 moyen, 3 difficile\n  text        String\n  explanation String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  authorId Int?\n  author   User? @relation(\"QuestionAuthor\", fields: [authorId], references: [id], onDelete: Cascade)\n\n  categoryId Int?\n  category   Category? @relation(fields: [categoryId], references: [id], onDelete: Restrict)\n\n  imageId Int?\n  image   Image? @relation(fields: [imageId], references: [id], onDelete: SetNull)\n\n  tags             Tag[]\n  answers          Answer[]\n  quizzes          QuizQuestion[]\n  attemptQuestions AttemptQuestion[]\n  userAnswers      UserAnswer[]\n\n  @@index([categoryId, difficulty])\n}\n\nmodel QuizQuestion {\n  quizId     Int\n  quiz       Quiz     @relation(fields: [quizId], references: [id], onDelete: Cascade)\n  questionId Int\n  question   Question @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  position   Int\n\n  @@id([quizId, questionId])\n  @@unique([quizId, position])\n}\n\nmodel Answer {\n  id        Int     @id @default(autoincrement())\n  text      String?\n  isCorrect Boolean @default(false)\n\n  questionId Int\n  question   Question @relation(fields: [questionId], references: [id], onDelete: Cascade)\n\n  imageId Int?\n  image   Image? @relation(fields: [imageId], references: [id], onDelete: SetNull)\n\n  userAnswers UserAnswer[]\n}\n\nmodel QuizAttempt {\n  id             Int       @id @default(autoincrement())\n  score          Int       @default(0)\n  totalQuestions Int       @default(0)\n  startedAt      DateTime  @default(now())\n  finishedAt     DateTime?\n\n  userId Int\n  user   User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  // Partie sur un quiz existant (null pour une partie générée)\n  quizId Int?\n  quiz   Quiz? @relation(fields: [quizId], references: [id], onDelete: SetNull)\n\n  // Partie générée : le score est rattaché à ce thème, pas à un quiz\n  categoryId Int?\n  category   Category? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  tagId      Int?\n  tag        Tag?      @relation(fields: [tagId], references: [id], onDelete: SetNull)\n  difficulty Int?\n\n  questions   AttemptQuestion[]\n  userAnswers UserAnswer[]\n\n  @@index([userId])\n  @@index([categoryId, tagId, difficulty])\n}\n\nmodel AttemptQuestion {\n  attemptId  Int\n  attempt    QuizAttempt @relation(fields: [attemptId], references: [id], onDelete: Cascade)\n  questionId Int\n  question   Question    @relation(fields: [questionId], references: [id], onDelete: Cascade)\n  position   Int\n\n  @@id([attemptId, questionId])\n  @@unique([attemptId, position])\n}\n\nmodel UserAnswer {\n  id        Int     @id @default(autoincrement())\n  isCorrect Boolean\n\n  attemptId Int\n  attempt   QuizAttempt @relation(fields: [attemptId], references: [id], onDelete: Cascade)\n\n  questionId Int\n  question   Question @relation(fields: [questionId], references: [id], onDelete: Cascade)\n\n  answerId Int?\n  answer   Answer? @relation(fields: [answerId], references: [id], onDelete: SetNull)\n\n  @@unique([attemptId, questionId])\n}\n\nmodel Image {\n  id            Int     @id @default(autoincrement())\n  src           String  @unique\n  alt           String\n  creditAuthor  String?\n  creditLicense String?\n  creditUrl     String?\n\n  questions Question[]\n  answers   Answer[]\n}\n\nmodel Tag {\n  id        Int           @id @default(autoincrement())\n  slug      String        @unique\n  questions Question[]\n  attempts  QuizAttempt[]\n}\n",
